import { LovelaceConfig } from 'custom-card-helpers';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function getLovelaceCast(): any {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  let root: any = document.querySelector('hc-main');
  root = root && root.shadowRoot;
  root = root && root.querySelector('hc-lovelace');
  root = root && root.shadowRoot;
  root = root && root.querySelector('hui-view');
  return root ? root.lovelace : null;
}

export function getLovelace(): LovelaceConfig | null {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  let root: any = document.querySelector('home-assistant');
  root = root && root.shadowRoot;
  root = root && root.querySelector('home-assistant-main');
  root = root && root.shadowRoot;
  root = root && root.querySelector('app-drawer-layout partial-panel-resolver, ha-drawer partial-panel-resolver');
  root = (root && root.shadowRoot) || root;
  root = root && root.querySelector('ha-panel-lovelace');
  root = root && root.shadowRoot;
  root = root && root.querySelector('hui-root');
  return root ? root.lovelace : null;
}

export function getLovelaceConfig(): LovelaceConfig | null {
  const ll = getLovelace() || getLovelaceCast();
  return ll?.config;
}

/**
 * The url path of the dashboard on screen - `lovelace` for the default one, which has no
 * path of its own in Home Assistant's eyes. Read from the dashboard where it says, and
 * otherwise from the address bar, which always starts with it.
 */
export function getDashboardPath(): string {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const ll: any = getLovelace() || getLovelaceCast();
  if (typeof ll?.urlPath === 'string' && ll.urlPath) return ll.urlPath;
  if (typeof window === 'undefined') return 'lovelace';
  return window.location.pathname.split('/').filter(Boolean)[0] || 'lovelace';
}

/**
 * The dashboard itself rather than its configuration, which is the only thing that can
 * save a change back. Null when there is nothing to save through - a cast session, or a
 * dashboard written in YAML, which cannot be edited from the interface at all.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function getLovelacePanel(): any {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const ll: any = getLovelace() || getLovelaceCast();
  return typeof ll?.saveConfig === 'function' ? ll : null;
}

/**
 * Puts text on the clipboard. Home Assistant is usually reached over plain http on a
 * local address, which is not a secure context, so navigator.clipboard is not there at
 * all for most people. The old selection-based way still works everywhere.
 */
export async function copyText(text: string): Promise<boolean> {
  if (navigator.clipboard?.writeText) {
    try {
      await navigator.clipboard.writeText(text);
      return true;
    } catch {
      // Permission refused or not allowed here; fall through to the old way.
    }
  }

  const area = document.createElement('textarea');
  area.value = text;
  area.setAttribute('readonly', '');
  area.style.cssText = 'position:fixed;top:-1000px;opacity:0;';
  document.body.appendChild(area);
  area.select();
  let copied = false;
  try {
    copied = document.execCommand('copy');
  } catch {
    copied = false;
  }
  area.remove();
  return copied;
}
